def user_balance(user_id):
    with DATA_LOCK:
        try:
            return max(0, int(BALANCES.get(str(user_id), 0) or 0))
        except (TypeError, ValueError):
            return 0

def adjust_balance(user_id, delta):

    key = str(user_id)
    with DATA_LOCK:
        try:
            current = max(0, int(BALANCES.get(key, 0) or 0))
            delta = int(delta)
        except (TypeError, ValueError):
            return False, 0
        if current + delta < 0:
            return False, current
        BALANCES[key] = current + delta
        if not _save_balances():
            BALANCES[key] = current
            return False, current
        return True, BALANCES[key]


def tg(method, payload=None, timeout=30):
    if not BOT_TOKEN:
        raise RuntimeError("Chưa đặt BOT_TOKEN cho bot @shopkeyvb_bot.")
    response = requests.post(
        f"https://api.telegram.org/bot{BOT_TOKEN}/{method}",
        json=payload or {}, timeout=timeout,
    )
    response.raise_for_status()
    data = response.json()
    if not data.get("ok"):
        raise RuntimeError(f"Telegram API {method}: {data}")
    return data.get("result")


def send_message(chat_id, text, markup=None, parse_mode=None):
    payload = {"chat_id": chat_id, "text": str(text or " ")[:4090], "disable_web_page_preview": True}
    if markup:
        payload["reply_markup"] = markup
    if parse_mode:
        payload["parse_mode"] = parse_mode
    try:
        return tg("sendMessage", payload, timeout=15)
    except Exception as exc:
        _log_error("sendMessage", exc)
        return None


def send_photo(chat_id, image_path, caption="", markup=None, parse_mode=None):
    if not image_path or not Path(image_path).is_file():
        return None
    data = {"chat_id": chat_id, "caption": str(caption or "")[:1024]}
    if markup:
        data["reply_markup"] = json.dumps(markup, ensure_ascii=False)
    if parse_mode:
        data["parse_mode"] = parse_mode
    try:
        with open(image_path, "rb") as f:
            response = requests.post(
                f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto",
                data=data,
                files={"photo": (Path(image_path).name, f, "image/jpeg" if Path(image_path).suffix.lower() in {".jpg", ".jpeg"} else "image/png")},
                timeout=25,
            )
        response.raise_for_status()
        result = response.json()
        if not result.get("ok"):
            raise RuntimeError(str(result))
        return result.get("result")
    except Exception as exc:
        _log_error("sendPhoto", exc)
        return None


