def invalidate_deposit_qr_messages(deposit_id, deposit_snapshot, reason):
    """Xóa mọi ảnh QR đã gửi cho đơn và đánh dấu QR không còn hiệu lực trong bot."""
    if not isinstance(deposit_snapshot, dict):
        return 0
    default_chat = str(deposit_snapshot.get("telegram_id") or "")
    entries = list(deposit_snapshot.get("qr_messages") or [])
    legacy_id = deposit_snapshot.get("qr_message_id")
    if legacy_id:
        entries.append({"chat_id": default_chat, "message_id": legacy_id})
    seen = set()
    deleted = 0
    for entry in entries:
        if isinstance(entry, dict):
            chat = str(entry.get("chat_id") or default_chat)
            msg_id = entry.get("message_id")
        else:
            chat, msg_id = default_chat, entry
        try:
            msg_id = int(msg_id)
            chat_id = int(chat)
        except (TypeError, ValueError):
            continue
        pair = (chat_id, msg_id)
        if pair in seen:
            continue
        seen.add(pair)
        if delete_message(chat_id, msg_id):
            deleted += 1
    with DATA_LOCK:
        current = DEPOSITS.get(str(deposit_id))
        if isinstance(current, dict):
            current["qr_invalidated_at"] = datetime.now().isoformat()
            current["qr_invalidated_reason"] = str(reason or "completed")
            current["qr_messages_deleted_count"] = deleted
            current["qr_messages"] = []
            current.pop("qr_message_id", None)
            _save_deposits()
    return deleted


