def money(value):
    try:
        return f"{int(value):,}".replace(",", ".") + " VNĐ"
    except Exception:
        return f"{value} VNĐ"


def parse_iso_ts(value):
    """Parse ISO datetimes consistently with timestamps created by datetime.now().

    Naive ISO values in older persisted records were written in the host's local
    timezone, so use the same local-time interpretation instead of forcing UTC.
    New deposit records also store created_ts (Unix epoch) to avoid ambiguity.
    """
    if not value:
        return None
    try:
        dt = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return dt.timestamp()  # aware values use their offset; naive values use host local time
    except Exception:
        return None


def deposit_created_epoch(deposit):
    """Return reliable creation epoch, preferring the explicit Unix timestamp."""
    if not isinstance(deposit, dict):
        return None
    try:
        value = float(deposit.get("created_ts"))
        if value > 0:
            return value
    except (TypeError, ValueError, OverflowError):
        pass
    return parse_iso_ts(deposit.get("created_at"))


def format_created(value):
    ts = parse_iso_ts(value)
    if ts is None:
        return str(value or "-")
    return datetime.fromtimestamp(ts, timezone(timedelta(hours=7))).strftime("%H:%M:%S | %d-%m-%Y")


