def expire_order(order):
    if not isinstance(order, dict) or str(order.get("status", "")).upper() not in {"WAITING_PAYMENT", "PENDING"}:
        return False
    if order.get("approval_requested_at"):
        return False
    created_ts = parse_iso_ts(order.get("created_at"))
    if created_ts is None or time.time() - created_ts < ORDER_PAYMENT_TIMEOUT:
        return False
    order["status"] = "CANCELLED"
    order["cancelled_at"] = datetime.now().isoformat()
    order["cancel_reason"] = "Quá hạn thanh toán 10 phút"
    _save_orders()
    return True


def open_order_for_user(chat_id):
    for order_id, order in reversed(list(ORDERS.items())):
        if not isinstance(order, dict) or str(order.get("telegram_id")) != str(chat_id):
            continue
        expire_order(order)
        status = str(order.get("status", "")).upper()
        if status in {"WAITING_APPROVAL", "PROCESSING"}:
            return order_id, order
    return None, None

