def create_order(chat_id, package_code, quantity, user_info):
    """Tạo đơn bằng số dư ví shop; không tạo QR/chuyển khoản ở bước mua key."""
    pkg = KEY_PURCHASE_PACKAGES.get(package_code)
    if not pkg:
        return None, "Gói key không hợp lệ."
    try:
        quantity = int(quantity)
    except (ValueError, TypeError):
        return None, "Số lượng key không hợp lệ."
    if quantity < 1:
        return None, "Số lượng tối thiểu là 1 key."

    total_price = int(pkg["price"]) * quantity
    with DATA_LOCK:
        # Cho phép cùng một người tạo nhiều đơn đang chờ Admin duyệt.
        # Mỗi đơn vẫn kiểm tra số dư và trừ tiền riêng bên trong khóa dữ liệu,
        # nên người dùng chỉ mua được khi còn đủ tiền cho đơn mới.
        current_balance = user_balance(chat_id)
        if current_balance < total_price:
            return None, "INSUFFICIENT_BALANCE"

        order_id = secrets.token_hex(4).upper()
        while order_id in ORDERS:
            order_id = secrets.token_hex(4).upper()
        order = {
            "order_id": order_id, "telegram_id": str(chat_id),
            "username": str(user_info.get("username") or user_info.get("first_name") or ""),
            "package_code": package_code, "package": pkg["package"], "label": pkg["label"],
            "duration_hours": pkg["duration_hours"], "is_forever": False,
            "quantity": quantity, "unit_price": int(pkg["price"]), "price": total_price,
            "status": "WAITING_APPROVAL", "created_at": datetime.now().isoformat(),
            "payment_wallet": "SỐ DƯ VÍ SHOP", "payment_account_name": "",
            "payment_account_number": "", "payment_content": "WALLET_BALANCE",
            "paid_from_balance": True, "wallet_deducted": total_price,
            "wallet_refunded": False, "key": None, "keys": [],
        }
        BALANCES[str(chat_id)] = current_balance - total_price
        ORDERS[order_id] = order
        if not _save_balances() or not _save_orders():
   
            BALANCES[str(chat_id)] = current_balance
            ORDERS.pop(order_id, None)
            _save_balances()
            _save_orders()
            return None, "Không lưu được đơn hàng. Vui lòng thử lại sau."
    return order_id, order

def ensure_payment_qr_file():
   
    try:
        if PAYMENT_QR_FILE.is_file() and PAYMENT_QR_FILE.stat().st_size > 1000:
            return PAYMENT_QR_FILE
        raw = base64.b64decode(_PAYMENT_QR_B64)
        with PAYMENT_QR_FILE.open("wb") as f:
            f.write(raw)
        if PAYMENT_QR_FILE.stat().st_size > 1000:
            return PAYMENT_QR_FILE
    except Exception as exc:
        _log_error("fallback QR", exc)
    return None



def emv_tlv(tag, value):
    value = str(value)
    if len(value) > 99:
        raise ValueError(f"Dữ liệu QR ở trường {tag} quá dài")
    return f"{tag}{len(value):02d}{value}"


def parse_emv_tlv(payload):
    """Đọc chuỗi EMV TLV theo từng trường tag/length/value."""
    fields = []
    i = 0
    while i < len(payload):
        if i + 4 > len(payload):
            raise ValueError("QR mẫu có cấu trúc TLV không hợp lệ")
        tag = payload[i:i + 2]
        try:
            length = int(payload[i + 2:i + 4])
        except ValueError as exc:
            raise ValueError("Độ dài trường QR mẫu không hợp lệ") from exc
        start = i + 4
        end = start + length
        if end > len(payload):
            raise ValueError("Trường QR mẫu bị thiếu dữ liệu")
        fields.append((tag, payload[start:end]))
        i = end
    return fields


def crc16_ccitt(payload):
    crc = 0xFFFF
    for byte in payload.encode("ascii"):
        crc ^= byte << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) & 0xFFFF if crc & 0x8000 else (crc << 1) & 0xFFFF
    return f"{crc:04X}"


