def _apply_vpbank_qr_style(image_path):
    """Thêm dấu V đỏ ở giữa và viền xanh mảnh như mẫu; không thay đổi dữ liệu QR."""
    try:
        from PIL import Image, ImageDraw

        source = Image.open(image_path).convert("RGB")
        width, height = source.size
        side = min(width, height)
        left = (width - side) // 2
        top = (height - side) // 2
        source = source.crop((left, top, left + side, top + side))

        margin = max(8, int(side * 0.012))
        output_side = side + margin * 2
        canvas = Image.new("RGB", (output_side, output_side), "white")
        canvas.paste(source, (margin, margin))
        draw = ImageDraw.Draw(canvas)
        border_width = max(2, int(side * 0.003))
        draw.rectangle(
            (1, 1, output_side - 2, output_side - 2),
            outline=(27, 49, 88), width=border_width
        )

        # Khoảng trắng ở tâm giúp dấu logo không lấn vào các vùng định vị QR.
        logo_box = max(56, int(side * 0.165))
        cx = output_side // 2
        cy = output_side // 2
        x0 = cx - logo_box // 2
        y0 = cy - logo_box // 2
        draw.rectangle(
            (x0, y0, x0 + logo_box, y0 + logo_box),
            fill=(255, 255, 255)
        )

        # V đỏ bo tròn và nét đỏ sẫm bên trái, được vẽ ở độ phân giải cao.
        scale = 4
        logo_w = int(logo_box * 0.98)
        logo_h = int(logo_box * 0.94)
        logo = Image.new("RGBA", (logo_w * scale, logo_h * scale), (255, 255, 255, 0))
        ld = ImageDraw.Draw(logo)
        def pt(x, y):
            return (int(x * scale), int(y * scale))
        stroke = max(8, int(logo_w * 0.28)) * scale
        p1 = pt(logo_w * 0.15, logo_h * 0.16)
        p2 = pt(logo_w * 0.50, logo_h * 0.83)
        p3 = pt(logo_w * 0.85, logo_h * 0.16)
        red = (239, 27, 46, 255)
        ld.line((p1, p2, p3), fill=red, width=stroke, joint="curve")
        for x, y in (p1, p2, p3):
            r = stroke // 2
            ld.ellipse((x - r, y - r, x + r, y + r), fill=red)
        # Màu đỏ sẫm chỉ nằm trên phần trong của nhánh trái như hình mẫu.
        dark_stroke = max(5, int(logo_w * 0.13)) * scale
        d1 = pt(logo_w * 0.25, logo_h * 0.19)
        d2 = pt(logo_w * 0.43, logo_h * 0.47)
        ld.line((d1, d2), fill=(169, 39, 43, 255), width=dark_stroke)
        for x, y in (d1, d2):
            r = dark_stroke // 2
            ld.ellipse((x - r, y - r, x + r, y + r), fill=(169, 39, 43, 255))
        resampling = getattr(Image, "Resampling", Image)
        logo = logo.resize((logo_w, logo_h), resampling.LANCZOS)
        canvas.paste(logo, (cx - logo_w // 2, cy - logo_h // 2), logo)
        canvas.save(image_path, format="PNG", optimize=True)
        return True
    except Exception as exc:
        _log_error("style dynamic QR", exc)
        return False


def dynamic_qr_path(order):
    """Tạo QR chuyển khoản động theo từng đơn, gắn sẵn số tiền và nội dung CK."""
    amount = int(order.get("price") or order.get("amount") or 0)
    transfer_code = str(order.get("payment_content") or "").strip()
    if amount <= 0 or not transfer_code:
        raise ValueError("Thiếu số tiền hoặc nội dung chuyển khoản cho QR")
    if not PAYMENT_ACCOUNT_NUMBER or not PAYMENT_BANK_CODE:
        raise ValueError("Thiếu PAYMENT_ACCOUNT_NUMBER hoặc PAYMENT_BANK_CODE")

    order_id = str(order.get("order_id") or secrets.token_hex(4).upper())
    path = DATA_DIR / f"shop_key_qr_{order_id}.png"
    bank_value = PAYMENT_BANK_CODE.strip()
    # Chuẩn hóa một số tên VPBank thường được nhập trong Environment.
    bank_value = {"VPBANK": "VPBank", "VPB": "VPBank", "970432": "VPBank"}.get(bank_value.upper(), bank_value)

    # Ưu tiên endpoint QR mà tài liệu SePay công bố: acc/bank/amount/des.
    # Quét QR sẽ điền trước tài khoản nhận, số tiền và nội dung chuyển khoản.
    providers = [
        (
            "SePay QR",
            "https://vietqr.app/img",
            {
                "acc": PAYMENT_ACCOUNT_NUMBER,
                "bank": bank_value,
                "amount": amount,
                "des": transfer_code,
                "template": "qronly",
                # Chỉ hiển thị hình QR; không in tên chủ TK, số TK hoặc số tiền
                # thành dòng chữ bên cạnh/bên dưới ảnh. Số tiền và nội dung vẫn
                # được mã hóa BÊN TRONG QR để ngân hàng tự điền khi quét.
                "showinfo": "false",
            },
        ),
        # Dự phòng nếu endpoint QR của SePay không khả dụng.
        (
            "VietQR fallback",
            f"https://img.vietqr.io/image/{quote(bank_value, safe='')}-{quote(PAYMENT_ACCOUNT_NUMBER, safe='')}-qr_only.png",
            # qr_only: chỉ ảnh QR, không kèm tên tài khoản hay thông tin in thêm.
            {"amount": amount, "addInfo": transfer_code},
        ),
    ]
    errors = []
    for provider_name, url, params in providers:
        try:
            response = requests.get(url, params=params, timeout=20)
            response.raise_for_status()
            content_type = str(response.headers.get("Content-Type") or "").lower()
            if not content_type.startswith("image/") or len(response.content) < 1000:
                raise RuntimeError(f"{provider_name} không trả về ảnh QR hợp lệ")
            path.write_bytes(response.content)
            _apply_vpbank_qr_style(path)
            return path
        except Exception as exc:
            errors.append(f"{provider_name}: {exc}")
            _log_error(f"dynamic QR {provider_name}", exc)
    raise RuntimeError("Không tạo được QR động; kiểm tra mã ngân hàng/số tài khoản/kết nối. " + " | ".join(errors))


