def request_approval(order_id, chat_id):
    with DATA_LOCK:
        order = ORDERS.get(order_id)
        if not isinstance(order, dict):
            return False, "Không tìm thấy đơn hàng."
        if str(order.get("telegram_id")) != str(chat_id):
            return False, "Bạn không có quyền gửi duyệt đơn này."
        if expire_order(order):
            return False, "Đơn đã hết hạn sau 10 phút. Hãy tạo đơn mới."
        status = str(order.get("status", "")).upper()
        if status == "WAITING_APPROVAL":
            return True, dict(order)
        if status in {"CANCELLED", "COMPLETED", "PROCESSING", "REJECTED"}:
            return False, f"Đơn đang ở trạng thái {status_text(status)}."
        if status not in {"WAITING_PAYMENT", "PENDING"}:
            return False, f"Trạng thái đơn không hợp lệ: {status}."
        order["status"] = "WAITING_APPROVAL"
        order["approval_requested_at"] = datetime.now().isoformat()
        _save_orders()
        snapshot = dict(order)
    send_admin_order_notice(snapshot)
    return True, snapshot


def issue_order(order_id, admin_chat_id):
    with DATA_LOCK:
        order = ORDERS.get(order_id)
        if not isinstance(order, dict):
            return False, "Không tìm thấy đơn hàng."
        if str(order.get("status", "")).upper() == "COMPLETED" and order_keys(order):
            return False, "Đơn đã cấp key trước đó; không phát hành lại để tránh cấp trùng."
        if str(order.get("status", "")).upper() not in {"PENDING", "WAITING_APPROVAL", "PROCESSING"}:
            return False, f"Đơn đang ở trạng thái {status_text(order.get('status'))}."
        quantity = int(order.get("quantity") or 1)
        if quantity < 1:
            return False, "Số lượng trong đơn không hợp lệ."
        order["status"] = "PROCESSING"
        order["approved_by"] = str(admin_chat_id)
        order["approved_at"] = datetime.now().isoformat()
        order.setdefault("keys", order_keys(order))
        issued = [str(k).strip() for k in order.get("keys", []) if str(k or "").strip()]
        order["keys"] = issued
        _save_orders()
        snapshot = dict(order)

    pkg = KEY_PURCHASE_PACKAGES.get(str(snapshot.get("package_code") or ""))
    if not pkg:
        with DATA_LOCK:
            ORDERS[order_id]["status"] = "WAITING_APPROVAL"
            _save_orders()
        return False, "Không tìm thấy cấu hình gói key."

    while len(issued) < quantity:
        index = len(issued)
        api_order_id = order_id if quantity == 1 else f"{order_id}-{index + 1:03d}"
        payload = {
            "package": pkg["package"], "order_id": api_order_id,
            "user_id": snapshot["telegram_id"], "username": snapshot.get("username", ""),
            "note": "telegram_purchase",
            "duration_hours": int(pkg["duration_hours"]),
        }
        headers = {"X-Server-Secret": KEY_SERVER_ADMIN_SECRET} if KEY_SERVER_ADMIN_SECRET else {}
        try:
            response = requests.post(f"{KEY_SERVER_URL}/api/issue_key", json=payload, headers=headers, timeout=25)
            data = response.json() if response.content else {}
        except Exception as exc:
            with DATA_LOCK:
                if order_id in ORDERS:
                    ORDERS[order_id]["status"] = "WAITING_APPROVAL"
                    ORDERS[order_id]["error"] = str(exc)
                    _save_orders()
            return False, f"Lỗi kết nối Key Server: {exc}"
        if response.status_code != 200 or not isinstance(data, dict) or not data.get("success"):
            msg = str(data.get("message", f"HTTP {response.status_code}")) if isinstance(data, dict) else f"HTTP {response.status_code}"
            with DATA_LOCK:
                if order_id in ORDERS:
                    ORDERS[order_id]["status"] = "WAITING_APPROVAL"
                    ORDERS[order_id]["error"] = msg
                    _save_orders()
            return False, f"Key Server chưa cấp được key: {msg}"
        if any([data.get("activated") is True, data.get("used") is True, data.get("redeemed_once") is True, bool(data.get("activated_at")), bool(data.get("used_at"))]):
            with DATA_LOCK:
                if order_id in ORDERS:
                    ORDERS[order_id]["status"] = "WAITING_APPROVAL"
                    ORDERS[order_id]["error"] = "Key Server trả về key đã kích hoạt; không gửi cho khách."
                    _save_orders()
            return False, "Key Server trả về key đã kích hoạt; đã dừng phát hành để tránh gửi key lỗi."
        key = str(data.get("key") or "").strip()
        if not key:
            with DATA_LOCK:
                if order_id in ORDERS:
                    ORDERS[order_id]["status"] = "WAITING_APPROVAL"
                    ORDERS[order_id]["error"] = "Key Server không trả về key."
                    _save_orders()
            return False, "Key Server không trả về key."
        issued.append(key)
        with DATA_LOCK:
            if order_id in ORDERS:
                ORDERS[order_id]["keys"] = list(issued)
                ORDERS[order_id]["key"] = issued[0]
                ORDERS[order_id]["issued_count"] = len(issued)
                ORDERS[order_id].pop("error", None)
                _save_orders()

    with DATA_LOCK:
        order = ORDERS[order_id]
        order["status"] = "COMPLETED"
        order["keys"] = list(issued)
        order["key"] = issued[0] if issued else None
        order["key_type"] = "VIP"
        order["completed_at"] = datetime.now().isoformat()
        order["activation_status"] = "NOT_ACTIVATED"
        _save_orders()
        result = dict(order)
    return True, result

