def new_deposit_code():
    # Nội dung chuyển khoản ngẫu nhiên 9 ký tự, không cố định tiền tố DK/NAP.
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
    return "".join(secrets.choice(alphabet) for _ in range(9))

def create_deposit(chat_id, amount, user_info):
    deposit_id = secrets.token_hex(4).upper()
    created_ts = time.time()
    deposit = {
        "deposit_id": deposit_id, "telegram_id": str(chat_id),
        "username": str(user_info.get("username") or user_info.get("first_name") or ""),
        "first_name": str(user_info.get("first_name") or ""),
        "amount": int(amount), "status": "WAITING_PAYMENT",
        "created_ts": created_ts,
        "created_at": datetime.fromtimestamp(created_ts, timezone.utc).isoformat(),
        "payment_wallet": PAYMENT_WALLET,
        "payment_account_name": PAYMENT_ACCOUNT_NAME, "payment_account_number": PAYMENT_ACCOUNT_NUMBER,
        "payment_content": new_deposit_code(),
    }
    with DATA_LOCK:
        while deposit_id in DEPOSITS:
            deposit_id = secrets.token_hex(4).upper()
            deposit["deposit_id"] = deposit_id
        DEPOSITS[deposit_id] = deposit
        if not _save_deposits():
            DEPOSITS.pop(deposit_id, None)
            return None
    return deposit


def expire_waiting_deposits(now=None):
    """Silently cancel unpaid deposits after 10 minutes and remove their QR messages.

    No Telegram cancellation notice is sent. New deposits use created_ts (epoch),
    preventing premature expiration caused by naive/local ISO timestamp parsing.
    """
    now = time.time() if now is None else float(now)
    expired = []
    originals = {}
    with DATA_LOCK:
        for deposit_id, deposit in DEPOSITS.items():
            if not isinstance(deposit, dict):
                continue
            if str(deposit.get("status") or "").upper() not in {"WAITING_PAYMENT", "WAITING_APPROVAL"}:
                continue
            created_ts = deposit_created_epoch(deposit)
            # Missing timestamps or a future timestamp must never trigger immediate cancellation.
            if created_ts is None or created_ts > now or now - created_ts < DEPOSIT_PAYMENT_TIMEOUT:
                continue
            originals[str(deposit_id)] = dict(deposit)
            deposit["status"] = "CANCELLED"
            deposit["cancelled_at"] = datetime.now(timezone.utc).isoformat()
            deposit["cancelled_by"] = "auto_timeout"
            deposit["cancel_reason"] = "Quá hạn thanh toán 10 phút"
        if originals and not _save_deposits():
            for deposit_id, original in originals.items():
                current = DEPOSITS.get(deposit_id)
                if isinstance(current, dict):
                    current.clear()
                    current.update(original)
            _save_deposits()
            return []
        expired = list(originals.keys())

    # Best-effort deletion of QR images only; intentionally do not message users.
    for deposit_id in expired:
        try:
            invalidate_deposit_qr_messages(deposit_id, originals.get(deposit_id, {}), "timeout")
        except Exception as exc:
            _log_error("delete expired deposit QR", exc)
    return expired


def active_deposit_for_user(chat_id):
    """Trả về đơn nạp còn hạn gần nhất của người dùng, nếu có."""
    now = time.time()
    with DATA_LOCK:
        candidates = []
        for deposit_id, deposit in DEPOSITS.items():
            if not isinstance(deposit, dict):
                continue
            if str(deposit.get("telegram_id")) != str(chat_id):
                continue
            if str(deposit.get("status") or "").upper() != "WAITING_PAYMENT":
                continue
            created_ts = deposit_created_epoch(deposit)
            if created_ts is None or created_ts > now or now - created_ts >= DEPOSIT_PAYMENT_TIMEOUT:
                continue
            candidates.append((created_ts, str(deposit_id), dict(deposit)))
        if not candidates:
            return None
        candidates.sort(key=lambda item: item[0], reverse=True)
        return candidates[0][2]


def start_deposit_expiry_worker():
    """Chạy bộ hẹn giờ độc lập, quét đơn nạp mỗi 10 giây."""
    def worker():
        while True:
            try:
                expire_waiting_deposits()
            except Exception as exc:
                _log_error("deposit expiry worker", exc)
            time.sleep(10)

    thread = threading.Thread(target=worker, name="deposit-expiry", daemon=True)
    thread.start()
    return thread


def _transaction_paid_within_deposit_window(payload, deposit):
    """Cho phép webhook đến trễ nếu ngày giao dịch cho biết đã chuyển trong 10 phút đầu."""
    created_ts = deposit_created_epoch(deposit)
    transaction_ts = parse_iso_ts(
        payload.get("transactionDate") or payload.get("transaction_date") or payload.get("transactionTime")
    )
    if created_ts is None or transaction_ts is None:
        return False
    return created_ts <= transaction_ts <= created_ts + DEPOSIT_PAYMENT_TIMEOUT


