def send_deposit_instructions(chat_id, deposit):
    """Gửi QR động chỉ khi đơn còn chờ; lưu mọi tin nhắn QR để xóa khi đơn kết thúc."""
    deposit_id = str(deposit.get("deposit_id") or "")
