def show_history(chat_id):
    """Hiển thị chung lịch sử nạp ví và mua key, xếp theo thời gian mới nhất."""
    with DATA_LOCK:
        purchase_rows = [dict(o) for o in ORDERS.values()
                         if isinstance(o, dict) and str(o.get("telegram_id")) == str(chat_id)]
        deposit_rows = [dict(d) for d in DEPOSITS.values()
                        if isinstance(d, dict) and str(d.get("telegram_id")) == str(chat_id)]

    entries = []
    for order in purchase_rows:
        created_ts = parse_iso_ts(order.get("created_at")) or 0
        entries.append((created_ts, "purchase", order))
    for deposit in deposit_rows:
        created_ts = deposit_created_epoch(deposit) or 0
        entries.append((created_ts, "deposit", deposit))
    entries.sort(key=lambda item: item[0], reverse=True)

    if not entries:
        send_message(chat_id, "📜 LỊCH SỬ ĐƠN\n\nBạn chưa có đơn nạp tiền hoặc mua key nào.", home_markup(chat_id))
        return

    lines = ["📜 LỊCH SỬ ĐƠN CỦA BẠN", ""]
    for _, kind, item in entries[:15]:
        if kind == "deposit":
            lines.append(
                f"💰 NẠP TIỀN | Mã nạp: {item.get('deposit_id', '-')}\n"
                f"💵 Số tiền: {money(item.get('amount', 0))}\n"
                f"📝 Nội dung CK: {item.get('payment_content', '-')}\n"
                f"📌 Trạng thái: {status_text(item.get('status'))}\n"
                f"🕒 {format_created(item.get('created_at'))}"
            )
        else:
            try:
                quantity = max(1, int(item.get("quantity") or 1))
            except (TypeError, ValueError):
                quantity = 1
            purchase_status = (
                "ĐÃ HOÀN TẤT"
                if str(item.get("status") or "").upper() == "COMPLETED"
                else status_text(item.get("status"))
            )
            lines.append(
                f"🛒 MUA KEY | Mã đơn: {item.get('order_id', '-')}\n"
                f"📦 Gói: {item.get('label', item.get('package', '-'))} × {quantity}\n"
                f"💰 Thành tiền: {money(item.get('price', 0))}\n"
                f"📌 Trạng thái: {purchase_status}\n"
                f"🕒 {format_created(item.get('created_at'))}"
            )
    send_message(chat_id, "\n\n".join(lines), home_markup(chat_id))


